mapper.select:
select event_id, work_id, chapter_no, seq, event_type, fact, actors, props, status,
       deadline_no, story_time, create_time, update_time
from sys_work_timeline_event
where work_id = #{workId}

    and status = #{status}


    and chapter_no < #{beforeNo}

order by chapter_no desc, seq desc

    limit #{limit}

select count(1) from sys_work_timeline_event
where work_id = #{workId} and status = '未兑现'

    and chapter_no < #{beforeNo}
